const now = 1_800_000_000_000;
const signer = createDatafnHmacRouteTickets({ activeKeyId: "a", keys: { a: "a".repeat(32) } });
function claims(overrides: Partial<DatafnRouteTicketClaims> = {}): DatafnRouteTicketClaims {
  return { version: 1, issuer: "canonical", audience: "prod-eu", subject: "opaque-user", namespace: "tenant",
    regionId: "eu", epoch: 1, scopes: ["query", "mutation", "websocket"], issuedAt: now,
    notBefore: now, expiresAt: now + 60_000, ticketId: "grant-1", ...overrides };
}
const request = (ticket: string) => new Request("https://eu.example/datafn/query", { headers: { [DATAFN_ROUTE_TICKET_HEADER]: ticket } });
const runtime = () => ({ verifier: signer, issuer: "canonical", audience: "prod-eu", now: () => now,
  authenticate: () => ({ namespace: "tenant", subject: "opaque-user" }) });
const verify = (value: DatafnRouteTicketClaims, scope: DatafnRouteScope = "query") =>
  validateDatafnRouteTicket({ request: request(signer.sign(value) as string), namespace: "tenant", regionId: "eu", scope, runtime: runtime() });

describe("regional route grants", () => {
  it("verifies gateway-only Ed25519 signatures with public keys, including key rotation", async () => {
    const first = generateKeyPairSync("ed25519");
    const second = generateKeyPairSync("ed25519");
    const gateway = createDatafnEd25519RouteTicketSigner({ activeKeyId: "first", privateKey: first.privateKey });
    const region = createDatafnEd25519RouteTicketVerifier({ publicKeys: { first: first.publicKey } });
    const ticket = gateway.sign(claims()) as string;
    expect(region.verify(ticket)).toEqual(claims());
    await expect(validateDatafnRouteTicket({ request: request(ticket), namespace: "tenant", regionId: "eu", scope: "query",
      runtime: { verifier: region, issuer: "canonical", audience: "prod-eu", now: () => now } })).resolves.toEqual(claims());
    const rotated = createDatafnEd25519RouteTicketVerifier({ publicKeys: { first: first.publicKey, second: second.publicKey } });
    expect(rotated.verify(ticket)).toEqual(claims());
    const next = createDatafnEd25519RouteTicketSigner({ activeKeyId: "second", privateKey: second.privateKey }).sign(claims()) as string;
    expect(rotated.verify(next)).toEqual(claims());
    expect(() => region.verify(next)).toThrow("DATAFN_ROUTE_TICKET_INVALID");
    expect(() => createDatafnEd25519RouteTicketVerifier({ publicKeys: { second: second.publicKey } }).verify(ticket)).toThrow();
    expect(() => createDatafnEd25519RouteTicketSigner({ activeKeyId: "bad", privateKey: first.publicKey })).toThrow("DATAFN_ROUTE_KEY_INVALID");
    expect(() => createDatafnEd25519RouteTicketVerifier({ publicKeys: { bad: first.privateKey } })).toThrow("DATAFN_ROUTE_KEY_INVALID");
    expect(() => createDatafnEd25519RouteTicketVerifier({ publicKeys: {
      bad: first.privateKey.export({ format: "pem", type: "pkcs8" }).toString(),
    } })).toThrow("DATAFN_ROUTE_KEY_INVALID");
  });

  it("rejects Ed25519 tampering, wrong issuer, and algorithm confusion", async () => {
    const { privateKey, publicKey } = generateKeyPairSync("ed25519");
    const gateway = createDatafnEd25519RouteTicketSigner({ activeKeyId: "a", privateKey });
    const region = createDatafnEd25519RouteTicketVerifier({ publicKeys: { a: publicKey } });
    const ticket = gateway.sign(claims()) as string;
    const [header, , signature] = ticket.split(".");
    const changed = `${header}.${Buffer.from(JSON.stringify(claims({ subject: "attacker" }))).toString("base64url")}.${signature}`;
    expect(() => region.verify(changed)).toThrow("DATAFN_ROUTE_TICKET_INVALID");
    expect(() => region.verify(signer.sign(claims()) as string)).toThrow("DATAFN_ROUTE_TICKET_INVALID");
    await expect(verifyDatafnRegionalTicketIdentity({ request: request(ticket), regionId: "eu",
      runtime: { verifier: region, issuer: "attacker", audience: "prod-eu", now: () => now } }))
      .rejects.toMatchObject({ code: "DATAFN_ROUTE_TICKET_INVALID" });
  });

  it("uses a verified ticket as sole regional identity and refuses session cookies", async () => {
    const { privateKey, publicKey } = generateKeyPairSync("ed25519");
