    const runtime = { verifier: createDatafnEd25519RouteTicketVerifier({ publicKeys: { a: publicKey } }),
      issuer: "canonical", audience: "prod-eu", now: () => now };
    const valid = request(ticket);
    await expect(verifyDatafnRegionalTicketIdentity({ request: valid, regionId: "eu", runtime })).resolves.toEqual(claims());
    await expect(validateDatafnRouteTicket({ request: valid, namespace: "tenant", regionId: "eu", scope: "query", runtime }))
      .resolves.toEqual(claims());
    await expect(validateDatafnRouteTicket({ request: new Request(valid, { headers: { cookie: "session=opaque", [DATAFN_ROUTE_TICKET_HEADER]: ticket } }),
      namespace: "tenant", regionId: "eu", scope: "query", runtime })).rejects.toMatchObject({ code: "DATAFN_ROUTE_FORBIDDEN" });
  });
  it("reuses a bounded grant independently of internal request nonces", async () => {
    await expect(verify(claims())).resolves.toEqual(claims());
