    ["session", { sessionBinding: "other-session" }],
  ] as [string, Partial<DatafnRouteTicketClaims>][])('rejects %s binding', async (_name, patch) => {
    await expect(verify(claims(patch))).rejects.toMatchObject({ executionStarted: false });
